import React, { useState, useEffect } from "react";
import { Box } from "@mui/material";
import { Getprofile } from "../../api/login/Login";

/**
 * ForensicSecurityWatermark
 * 
 * Enterprise Banking Forensic Watermarking:
 * - Stamps the User Name, Mobile Number, Role, and Live Dynamic Timestamp diagonally across all screens.
 * - Ultra-light, elegant opacity so dashboard cards and numbers remain 100% crystal clear.
 * - Complete leak prevention: Any camera photo, screenshot, or recording contains the permanent forensic identity stamp.
 * - Zero interaction blockage: Uses `pointer-events: none`.
 */
const ForensicSecurityWatermark = ({ customText, profileData, fixed = true }) => {
  const [profile, setProfile] = useState(profileData || null);
  const [timestamp, setTimestamp] = useState("");

  useEffect(() => {
    if (!profile) {
      Getprofile()
        .then((res) => {
          if (res?.data?.data) {
            setProfile(res.data.data);
          }
        })
        .catch(() => { });
    }
  }, [profile]);

  useEffect(() => {
    const updateTime = () => {
      const now = new Date();
      const pad = (n) => String(n).padStart(2, "0");
      const dateStr = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
      const timeStr = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
      setTimestamp(`${dateStr} ${timeStr}`);
    };

    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, []);

  const name =
    profile?.name ||
    profile?.pan_name ||
    localStorage.getItem("pan_name") ||
    localStorage.getItem("name") ||
    "SAURAV SWARAJ";

  const mobile =
    profile?.mobile ||
    localStorage.getItem("userNumber") ||
    localStorage.getItem("mobile") ||
    "";

  const role =
    profile?.user_type_id?.user_type ||
    localStorage.getItem("userType") ||
    "Retailer";

  const watermarkLine =
    customText ||
    `${name.toUpperCase()} • ${mobile ? mobile + " • " : ""}${role} • ${timestamp}`;

  const rows = [0, 1, 2, 3, 4, 5, 6, 7];
  const cols = [0, 1, 2, 3];

  return (
    <Box
      sx={{
        position: fixed ? "fixed" : "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        width: fixed ? "100vw" : "100%",
        height: fixed ? "100vh" : "100%",
        overflow: "hidden",
        pointerEvents: "none !important",
        zIndex: 999999,
        userSelect: "none",
        WebkitUserSelect: "none",
        display: "flex",
        flexDirection: "column",
        justifyContent: "space-around",
        opacity: 0.10,
      }}
    >
      {rows.map((r) => (
        <Box
          key={r}
          sx={{
            display: "flex",
            justifyContent: "space-around",
            width: "160%",
            marginLeft: "-30%",
            transform: "rotate(-18deg)",
            my: 2.5,
          }}
        >
          {cols.map((c) => (
            <Box
              key={c}
              sx={{
                fontSize: "12px",
                fontWeight: 700,
                letterSpacing: 1.2,
                color: "#0f172a",
                whiteSpace: "nowrap",
                px: 3,
                fontFamily: "monospace",
              }}
            >
              🔒 {watermarkLine}
            </Box>
          ))}
        </Box>
      ))}
    </Box>
  );
};

export default ForensicSecurityWatermark;
